import { getConfig, getKV, setKV, getFile, putFile, delFile, allFiles,
         enqueue, queued, clearQueue } from './store.js';
import { parse, serialize } from './md.js';

const API = 'https://api.github.com';

class SyncError extends Error {
  constructor(message, status) { super(message); this.status = status; }
}

async function auth() {
  const c = await getConfig();
  if (!c) throw new SyncError('Not set up yet');
  return c;
}

function rest(path, { method = 'GET', body, headers = {}, config } = {}) {
  return fetch(API + path, {
    method,
    headers: {
      Authorization: `Bearer ${config.token}`,
      Accept: 'application/vnd.github+json',
      'X-GitHub-Api-Version': '2022-11-28',
      ...(body ? { 'Content-Type': 'application/json' } : {}),
      ...headers
    },
    body: body ? JSON.stringify(body) : undefined
  });
}

async function ok(r, what) {
  if (r.ok) return r.status === 204 ? null : r.json();
  const { message = '' } = await r.json().catch(() => ({}));
  throw new SyncError(
    r.status === 401 ? 'Token rejected (401) - expired or mistyped.'
    : r.status === 403 ? `Forbidden (403) - the token likely lacks "Contents: read and write" here. ${message}`
    : r.status === 404 ? 'Not found (404) - check owner, repo and that the token can see it.'
    : `${what} failed: ${r.status} ${message}`, r.status);
}

const encode = s => {
  const bytes = new TextEncoder().encode(s);
  let bin = '';
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin);
};
const decode = b64 =>
  new TextDecoder().decode(Uint8Array.from(atob(b64.replace(/\s/g, '')), c => c.charCodeAt(0)));

export async function testConnection(config) {
  const repo = await ok(await rest(`/repos/${config.owner}/${config.repo}`, { config }), 'repo read');
  return { name: repo.full_name, private: repo.private, empty: repo.size === 0 };
}

// ---- pull: 304-guarded, fetches only what changed ----
// Also the first mirror: with no stored ETag it fetches the tree and every blob in it.

export async function pull(prefix = '') {
  const c = await auth();
  const etag = await getKV('commitEtag');
  const r = await rest(`/repos/${c.owner}/${c.repo}/commits/${c.branch}`,
    { config: c, headers: etag ? { 'If-None-Match': etag } : {} });
  if (r.status === 304) return { changed: 0, unchanged: true };
  if (r.status === 409) return { changed: 0, empty: true };
  await ok(r, 'commit check');
  await setKV('commitEtag', r.headers.get('ETag'));

  const tree = await ok(await rest(
    `/repos/${c.owner}/${c.repo}/git/trees/${c.branch}?recursive=1`, { config: c }), 'tree read');
  if (tree.truncated) throw new SyncError('Tree listing truncated - repo too large for a flat pull.');

  const remote = new Map(tree.tree
    .filter(t => t.type === 'blob' && t.path.endsWith('.md') && t.path.startsWith(prefix))
    .map(t => [t.path, t.sha]));
  const local = new Map((await allFiles(prefix)).map(f => [f.path, f.oid]));

  let changed = 0;
  for (const [path, sha] of remote) {
    if (local.get(path) === sha) continue;
    const blob = await ok(await rest(`/repos/${c.owner}/${c.repo}/git/blobs/${sha}`, { config: c }), 'blob read');
    await putFile({ path, text: decode(blob.content), oid: sha });
    changed++;
  }
  for (const path of local.keys()) if (!remote.has(path)) { await delFile(path); changed++; }
  return { changed };
}

// ---- writes: queue locally, drain as one atomic commit ----

export async function write(path, text) {
  const existing = await getFile(path);
  await putFile({ path, text, oid: existing?.oid });
  await enqueue({ op: 'put', path, text, baseOid: existing?.oid ?? null });
}

export async function remove(path) {
  const existing = await getFile(path);
  await delFile(path);
  await enqueue({ op: 'del', path, baseOid: existing?.oid ?? null });
}

export async function drain(message, retry = true) {
  const items = await queued();
  if (!items.length) return { committed: 0, conflicts: [] };
  const c = await auth();

  let parent = null, baseTree = null;
  const refRes = await rest(`/repos/${c.owner}/${c.repo}/git/ref/heads/${c.branch}`, { config: c });
  const fresh = refRes.status === 409 || refRes.status === 404;   // empty repo: no ref yet
  if (fresh) return initialise(c, items, message, retry);

  parent = (await ok(refRes, 'ref read')).object.sha;
  baseTree = (await ok(await rest(
    `/repos/${c.owner}/${c.repo}/git/commits/${parent}`, { config: c }), 'commit read')).tree.sha;

  // A queued change whose base SHA no longer matches the remote blob is a real conflict:
  // remote keeps the path, ours is committed beside it. Nothing is discarded.
  const conflicts = [];
  {
    const tree = await ok(await rest(
      `/repos/${c.owner}/${c.repo}/git/trees/${c.branch}?recursive=1`, { config: c }), 'tree read');
    const remote = new Map(tree.tree.filter(t => t.type === 'blob').map(t => [t.path, t.sha]));
    const stamp = new Date().toISOString().slice(0, 10).replace(/-/g, '');
    for (const it of items) {
      const live = remote.get(it.path);
      if (!it.baseOid || !live || live === it.baseOid) continue;
      const blob = await ok(await rest(`/repos/${c.owner}/${c.repo}/git/blobs/${live}`, { config: c }), 'blob read');
      await putFile({ path: it.path, text: decode(blob.content), oid: live });  // theirs wins the path
      const original = it.path;
      it.path = original.replace(/\.md$/, `.conflict-${stamp}.md`);
      if (it.op === 'put') {
        const { data, body } = parse(it.text);
        it.text = serialize({ ...data, conflictOf: original }, body);
      }
      conflicts.push({ path: original, keptAs: it.path });
    }
  }

  const entries = [];
  for (const it of items) {
    if (it.op === 'del') { entries.push({ path: it.path, mode: '100644', type: 'blob', sha: null }); continue; }
    const blob = await ok(await rest(`/repos/${c.owner}/${c.repo}/git/blobs`,
      { config: c, method: 'POST', body: { content: encode(it.text), encoding: 'base64' } }), 'blob create');
    entries.push({ path: it.path, mode: '100644', type: 'blob', sha: blob.sha, _text: it.text });
  }

  const tree = await ok(await rest(`/repos/${c.owner}/${c.repo}/git/trees`, {
    config: c, method: 'POST',
    body: { base_tree: baseTree, tree: entries.map(strip) }
  }), 'tree create');

  const commit = await ok(await rest(`/repos/${c.owner}/${c.repo}/git/commits`, {
    config: c, method: 'POST',
    body: { message: message || `${items.length} change(s) from Mine`, tree: tree.sha, parents: [parent] }
  }), 'commit create');

  {
    const r = await rest(`/repos/${c.owner}/${c.repo}/git/refs/heads/${c.branch}`, {
      config: c, method: 'PATCH', body: { sha: commit.sha, force: false }
    });
    if (!r.ok) {
      // Rejected: someone pushed elsewhere. Rebase onto the new base and retry once -
      // this succeeds because nearly every write is a create at a fresh path.
      if (retry && (r.status === 422 || r.status === 409)) { await pull(); return drain(message, false); }
      await ok(r, 'ref update');
    }
  }

  for (const e of entries) {
    if (e.sha === null) await delFile(e.path);
    else await putFile({ path: e.path, text: e._text, oid: e.sha });
  }
  await clearQueue();
  await setKV('commitEtag', null);   // our own commit changed the ref
  return { committed: items.length, commit: commit.sha, conflicts };
}

const strip = ({ _text, ...e }) => e;

// A repo with no commits rejects the Git Data API outright: POST /git/blobs answers
// 409 "Git Repository is empty". Only the Contents API can create the first commit, so the
// first queued file goes that way and the rest drain normally once a history exists.
async function initialise(c, items, message, retry) {
  const first = items.find(i => i.op === 'put');
  if (!first) { await clearQueue(); return { committed: 0, conflicts: [] }; }

  const res = await ok(await rest(`/repos/${c.owner}/${c.repo}/contents/${encodeURI(first.path)}`, {
    config: c, method: 'PUT',
    body: {
      message: message || 'Initial commit from Mine',
      content: encode(first.text),
      branch: c.branch
    }
  }), 'initial commit');

  await putFile({ path: first.path, text: first.text, oid: res.content.sha });

  const rest_ = items.filter(i => i !== first);
  await clearQueue();
  await setKV('commitEtag', null);
  if (!rest_.length) return { committed: 1, commit: res.commit.sha, conflicts: [] };

  for (const it of rest_) await enqueue(it);
  const more = await drain(message, retry);
  return { ...more, committed: more.committed + 1, commit: more.commit || res.commit.sha };
}

// The shell: the top pane, navigation, the date picker, the zoom, the hamburger's menu, the sync
// line, and which view the big calendar window holds.
import { getConfig, getKV, setKV, queuedCount } from '../shared/store.js';
import { pull, drain } from '../shared/github.js';
import {
  loadModel, todayKey, addDays, addMonths, partsOf, monthGrid, weekStartOf, isoWeek, setZone,
  sprintRange, sprintOf
} from './data.js';
import {
  S, $, el, phone, dayLabel, icon, weekLetters, currentSprint, openPop, closePops
} from './ui.js';
import { renderView, wireView, openDayPop } from './views.js';
import { renderKanban } from './kanban.js';
import { escapeEntry } from './popup.js';
import { openFilter, openPanel, renderFilter } from './settings.js';
import { loadPrefs, applyTheme, weekdayName } from '../shared/prefs.js';

let pick = { mode: 'days', y: 2026, m: 0, base: 0 };

// ---- rendering -----------------------------------------------------------------------------

function render() {
  const k = S.view.mode === 'K';
  $('#period-label').textContent = periodLabel();

  // One slot carries the way to the other kind of view. The board is not a zoom step, which is
  // why it has a slot of its own rather than a place in the cycle the label walks.
  $('#board').replaceChildren(icon(k ? 'cal' : 'board'));
  $('#board').setAttribute('aria-label', k ? 'Back to the month view' : 'Kanban');
  $('#period').setAttribute('aria-label', k ? 'Pick a sprint' : 'Pick a date');

  if (k) renderKanban($('#view'));
  else renderView($('#view'));
  renderZoom();
  renderFilter();
}

// The pane has to fit a phone, so every label is short. The month name is the device locale's
// abbreviation, upper-cased - short beats English.
const shortMonth = key => new Date(`${key}T12:00:00`)
  .toLocaleDateString(undefined, { month: 'short' }).replace(/\./g, '').toUpperCase();

function periodLabel() {
  const { mode, anchor } = S.view;
  const [y, , d] = partsOf(anchor);
  if (mode === 'D')
    return `${weekdayName(anchor, 'short').slice(0, 2).toUpperCase()} ${d}/${shortMonth(anchor)}`;
  if (mode === 'W') {
    // The ISO number is in the label whether or not the gutter is on, and the month is the one
    // the row's fourth day is in - the rule the gutter uses, so the two cannot disagree.
    const a = weekStartOf(anchor, S.prefs.weekStart);
    return `W${isoWeek(addDays(a, 3))}/${shortMonth(addDays(a, 3))}`;
  }
  if (mode === 'M') return `${shortMonth(anchor)}/${String(y).slice(2)}`;
  if (mode === 'Y') return String(y);
  return String(S.view.sprint);
}

// ---- the zoom ------------------------------------------------------------------------------
// A magnifier beside the view switch, offering what the view it was opened in can do and nothing
// else: the four periods in a calendar view, the board's two orientations on the board. It
// replaces the label's old cycle, which asked up to three taps to reach a view and never said
// which one you were in.

const PERIODS = [['D', 'day'], ['W', 'week'], ['M', 'month'], ['Y', 'year']];
const ORIENTS = [['vert', 'vertical'], ['horz', 'horizontal']];

function renderZoom() {
  const board = S.view.mode === 'K';
  const rows = board
    ? ORIENTS.map(([v, text]) => [v, text, S.prefs.boardOrientation === v, setOrientation])
    : PERIODS.map(([v, text]) => [v, text, S.view.mode === v, setMode]);
  $('#zoom-body').replaceChildren(...rows.map(([v, text, on, pick]) => {
    const b = el('button', `zrow${on ? ' on' : ''}`);
    b.type = 'button';
    b.setAttribute('aria-pressed', String(on));
    b.append(el('span', 'dot'), el('span', '', text));
    b.addEventListener('click', () => pick(v));
    return b;
  }));
}

function setMode(mode) {
  S.view.mode = mode;
  closePops();
  render();
}

// Remembered per device: it is a preference about this screen, like confirm discard. The
// calendar's own zoom is not - the app opens on the month, on today, as it always has.
async function setOrientation(v) {
  S.prefs.boardOrientation = v;
  await setKV('calendar.boardOrientation', v);
  S.view.col = 0;
  closePops();
  render();
}

$('#zoom-btn').addEventListener('click', () => {
  if (!$('#zoom-pop').hidden) return closePops();
  closePops();
  renderZoom();
  openPop($('#zoom-pop'), $('#zoom-btn'));
});

// ---- navigation ----------------------------------------------------------------------------

$('#board').addEventListener('click', () => {
  if (S.view.mode === 'K') S.view.mode = 'M';
  else {
    S.view.mode = 'K';
    S.view.sprint = sprintOf(S.view.anchor, S.model.settings) || currentSprint();
  }
  closePops();
  render();
});

function step(dir) {
  const v = S.view;
  if (v.mode === 'D') v.anchor = addDays(v.anchor, dir);
  else if (v.mode === 'W') v.anchor = addDays(v.anchor, 7 * dir);
  else if (v.mode === 'M') v.anchor = addMonths(v.anchor, dir);
  else if (v.mode === 'Y') v.anchor = addMonths(v.anchor, 12 * dir);
  else v.sprint = Math.max(1, v.sprint + dir);
  closePops();
  render();
}
$('#prev').addEventListener('click', () => step(-1));
$('#next').addEventListener('click', () => step(1));

// There is no jump-to-today button and no `+` in the pane: today is the highlighted day in the
// dropdown, and an entry is created where it will live - a cell, the day preview, or a kanban
// column header.

for (const [id, name] of [['#home', 'house'], ['#zoom-btn', 'zoom'], ['#menu-btn', 'menu'],
  ['#day-add', 'plus'], ['#day-close', 'x'], ['#sub-close', 'x'], ['#settings-close', 'x'],
  ['#filter-close', 'x'], ['#fpop-close', 'x']])
  $(id).append(icon(name));

// ---- the hamburger's menu ------------------------------------------------------------------
// Two errands behind one button, each named before it is opened and each opening on its own. The
// button used to open both at once in a single panel, where a heading was the only thing telling
// a group you hide this afternoon from the week's first day, and the filter had no room to list
// its groups without pushing the settings off the screen.

const MENU = [['filter', 'filter', openFilter], ['gear', 'settings', openPanel]];

function openMenu() {
  if (!$('#menu-pop').hidden) return closePops();
  closePops();
  $('#menu-body').replaceChildren(...MENU.map(([ic, text, open]) => {
    const b = el('button', 'mrow');
    b.type = 'button';
    b.append(icon(ic), el('span', '', text));
    b.addEventListener('click', open);   // each one closes the menu on its way in
    return b;
  }));
  openPop($('#menu-pop'), $('#menu-btn'), 'right');
}

$('#menu-btn').addEventListener('click', openMenu);
$('#filter-close').addEventListener('click', closePops);
$('#settings-close').addEventListener('click', closePops);

// ---- the dropdown date picker --------------------------------------------------------------
// A month at a time, a 9-year grid, or - in the kanban - a list of sprints.

// The label opens the picker, and that is all it does, in every view and on both platforms. The
// caret existed only because the label's own tap was taken by the zoom; the zoom is a button of
// its own now, so the label is free to be the one thing it was always read as.
function openPicker() {
  if (!$('#picker').hidden) return closePops();
  closePops();
  const [y, m] = partsOf(S.view.anchor);
  pick = S.view.mode === 'K'
    ? { mode: 'sprints', base: Math.max(1, S.view.sprint - 4) }
    : { mode: 'days', y, m: m - 1, base: y - 8 };
  renderPicker();
  openPop($('#picker'), $('#period'), 'right');
}
$('#period').addEventListener('click', openPicker);

// There is no swipe. The label was swiped only because a phone's pane had no `‹` `›` to press;
// they are on its second row now, and a gesture doing what a visible button does is a second
// mechanism for one action. So no sideways gesture does anything, in any view, and nothing has
// to be told apart from a card drag on the board or a scroll in a grid.

$('#pick-title').addEventListener('click', () => {
  if (pick.mode === 'sprints') return;
  pick.mode = pick.mode === 'days' ? 'years' : 'days';
  pick.base = pick.y - 8;
  renderPicker();
});
$('#pick-prev').addEventListener('click', () => pagePicker(-1));
$('#pick-next').addEventListener('click', () => pagePicker(1));

function pagePicker(dir) {
  if (pick.mode === 'years') pick.base += dir * 9;
  else if (pick.mode === 'sprints') pick.base = Math.max(1, pick.base + dir * 9);
  else {
    const m = pick.m + dir;
    pick.y += Math.floor(m / 12);
    pick.m = (m + 12) % 12;
  }
  renderPicker();
}

function renderPicker() {
  const body = $('#pick-body');

  if (pick.mode === 'sprints') {
    $('#pick-label').textContent = 'Sprints';
    body.className = 'pick-body sprints';
    body.replaceChildren(...Array.from({ length: 9 }, (_, i) => {
      const r = sprintRange(pick.base + i, S.model.settings);
      // The sprint today falls in reads `current` and carries the brighter background; the
      // selected one is marked, not renamed, so the two can be the same row.
      const cur = r.n === currentSprint();
      const b = el('button', `pk wide${cur ? ' cur' : ''}${r.n === S.view.sprint ? ' now' : ''}`,
        `${cur ? 'current' : `Sprint ${r.n}`} · ${dayLabel(r.start)} – ${dayLabel(r.end)}`);
      b.type = 'button';
      b.addEventListener('click', () => {
        closePops();
        S.view.sprint = r.n;
        S.view.anchor = r.start;
        render();
      });
      return b;
    }));
    return;
  }

  if (pick.mode === 'years') {
    // 9 years ending with the current one; the arrows page by 9.
    $('#pick-label').textContent = `${pick.base} – ${pick.base + 8}`;
    body.className = 'pick-body years';
    body.replaceChildren(...Array.from({ length: 9 }, (_, i) => {
      const y = pick.base + i;
      const b = el('button', `pk${y === partsOf(S.view.anchor)[0] ? ' now' : ''}`, String(y));
      b.type = 'button';
      b.addEventListener('click', () => { pick = { ...pick, mode: 'days', y }; renderPicker(); });
      return b;
    }));
    return;
  }

  $('#pick-label').textContent =
    new Date(pick.y, pick.m, 1, 12).toLocaleDateString(undefined, { month: 'long', year: 'numeric' });
  body.className = 'pick-body days';
  body.replaceChildren(
    ...weekLetters().map(([n]) => el('span', 'wh', n)),
    ...monthGrid(pick.y, pick.m, S.prefs.weekStart).map(k => {
      const [, mm, dd] = partsOf(k);
      const b = el('button', `pk${mm !== pick.m + 1 ? ' out' : ''}${k === todayKey() ? ' now' : ''}`,
        String(dd));
      b.type = 'button';
      b.addEventListener('click', () => {
        closePops();
        S.view.anchor = k;
        render();
        // Picking a date in a view that cannot show the day's entries in place opens the preview.
        if (S.view.mode === 'Y' || (S.view.mode === 'M' && phone())) openDayPop(k);
      });
      return b;
    }));
}

$('#scrim').addEventListener('click', closePops);
addEventListener('keydown', e => {
  if (e.key !== 'Escape') return;
  if (!$('#ask').hidden) $('#ask-keep').click();
  else if (!$('#sub').hidden) $('#sub-close').click();
  else if (!$('#popup').hidden) escapeEntry();
  else closePops();
});
matchMedia('(min-width: 600px)').addEventListener('change', () => { closePops(); render(); });

// ---- sync ----------------------------------------------------------------------------------

function status(text, bad) {
  const s = $('#sync');
  s.textContent = text;
  s.classList.toggle('bad', !!bad);
}

async function showSync() {
  const n = await queuedCount();
  status(n ? `${n} change(s) pending` : 'in sync');
}

// Every write reaches the local mirror first, so the view is already right and the push can run
// behind it. One drain at a time, and failures and conflicts are reported here rather than in
// the popup the user has already left.
let chain = Promise.resolve();
function push(message) {
  chain = chain.then(async () => {
    status('pushing…');
    try {
      const r = await drain(message);
      if (r.conflicts?.length)
        status(`${r.conflicts.length} change(s) kept beside the remote version as .conflict files — review them`, true);
      else await showSync();
    } catch (err) {
      status(`not pushed: ${err.message}`, true);
    }
  });
}

async function refresh() {
  if (await queuedCount()) return showSync();
  status('checking…');
  try {
    const r = await pull();                    // whole repo: the mirror and the ETag are shared
    if (!r.unchanged) { S.model = await loadModel(); render(); }
    status(r.empty ? 'repo is empty' : r.unchanged ? 'in sync' : `in sync — ${r.changed} file(s) updated`);
  } catch (err) {
    status(err.message, true);
